  "onboarding.templates.wiseDiscountHint":
    "A payment through Stripe costs you Stripe's processing fee, charged by Stripe at the rate it sets for your country. A Wise transfer never passes through Stripe, so it costs you no processing fee and you can pass that saving on to your student. To be safe we size the suggested discount with our own deliberately high estimate — {rate}% plus a small fixed fee, which is an international card with currency conversion — so most payments cost you less than we assumed and the Wise price never leaves you worse off. Both prices stay editable.",
