  "web.settings.materialStyle.title": "AI material style",
  "web.settings.materialStyle.subtitle":
    "Tune how the AI writes your materials. Applies to every material you generate — class content and your library.",
  "web.settings.materialStyle.cardTitle": "How the AI writes",
  "web.settings.materialStyle.cardDescription":
    "These preferences are added to every generation. They don't change which language you teach or the structure you pick — only the tone and style.",
  "web.settings.materialStyle.tone.label": "Tone",
