  "web.settings.materialStyle.hubLink": "AI style",
  // Section 2 of the AI-material-style form: the two free-text fields.
  "web.settings.materialStyle.words.title": "In your own words",
  "web.settings.materialStyle.words.description":
    "What the dials above can't say — the variety of the language you teach, and any note you want applied to every material.",
  // Per-option effect lines. Each paraphrases the directive the prompt builder
  // actually sends (lib/materials/prompt.ts), so a control explains what it
  // does instead of leaving the teacher to guess from its one-word label.
  // Keep them in step with those directives.
  "web.settings.materialStyle.tone.effect.auto":
    "The AI picks a register that suits each material.",
  "web.settings.materialStyle.tone.effect.casual":
    "Warm and conversational, like a friendly teacher chatting — everyday words and contractions, nothing stiff.",
  "web.settings.materialStyle.tone.effect.friendly":
    "Clear, warm and encouraging. Plain-spoken, but not slangy.",
  "web.settings.materialStyle.tone.effect.neutral":
    "Plain and even — neither especially casual nor formal.",
  "web.settings.materialStyle.tone.effect.academic":
    "Formal and precise, with full, well-structured explanations.",
  "web.settings.materialStyle.age.effect.auto": "The AI writes without assuming an age.",
  "web.settings.materialStyle.age.effect.kids":
    "Short, lively sentences, simple concrete words, and very clear instructions.",
  "web.settings.materialStyle.age.effect.teens":
    "Pitched to teenage interests — engaging without being childish.",
  "web.settings.materialStyle.age.effect.adults":
    "Real-world examples that respect an adult reader, with no childish framing.",
  "web.settings.materialStyle.vocab.label": "Vocabulary",
  "web.settings.materialStyle.vocab.hint":
    "How hard the words are — a separate dial from the language level, so a C1 class can still be written with familiar vocabulary. A choice you make for one class beats this default.",
  "web.settings.materialStyle.vocab.basic": "Basic",
  "web.settings.materialStyle.vocab.everyday": "Everyday",
  "web.settings.materialStyle.vocab.advanced": "Advanced",
  "web.settings.materialStyle.vocab.native": "Native",
  "web.settings.materialStyle.vocab.effect.basic":
    "Only the most common words. Rare synonyms and idioms are avoided, even at a high level.",
  "web.settings.materialStyle.vocab.effect.everyday":
    "Normal conversational words. The default, and the safest for understanding.",
  "web.settings.materialStyle.vocab.effect.advanced":
    "Less frequent words, some idioms, and richer phrasing where they fit naturally.",
  "web.settings.materialStyle.vocab.effect.native":
    "Rare words, idioms, and literary, academic or regional expressions, used freely.",
