  "web.settings.payments.feesTitle": "Your plan and Stripe's fee are separate",
  "web.settings.payments.feesBody":
    "You pay SpiralClass for the software. You pay Stripe for handling payments made through Stripe — it charges that fee to your own account, at the rate it sets for your country and the method your student used, cards and any local option it offers alike. SpiralClass receives no part of it and takes no commission on your lesson income. A Wise transfer never passes through Stripe and carries no Stripe fee.",
