  "web.about.meta.title": "About",
  "web.about.meta.description":
    "Why SpiralClass exists, and who built it — a teacher and a developer solving the problem they lived.",
  "web.manifest.description": "Scheduling, payments and reminders for teachers of any subject.",
  "web.og.sub": "Scheduling, payments and automatic reminders for teachers of any subject.",
  "web.og.subWithStripe":
    "Scheduling, Stripe payments and automatic reminders for teachers of any subject.",
  "web.landing.meta.title": "SpiralClass — Scheduling, payments, and reminders for teachers",
  "web.landing.meta.description":
    "Share your booking link, get paid via Stripe or Wise, and send automatic reminders to your students. Start with {days} days of Pro free, no card needed.",
  "web.layout.meta.description":
    "SpiralClass organizes your classes, payments, and reminders so you can teach any subject without the mental load.",
  "web.pricing.meta.title": "Pricing",
  "web.pricing.meta.description":
    "Free-forever plan and Pro at {monthly} per month. Try Pro for {days} days with no card — SpiralClass never takes a share of what your students pay you.",
  "web.help.meta.title": "Help center",
  "web.help.meta.description": "How payments, plans, and bookings work on SpiralClass.",
  "web.terms.meta.title": "Terms of Service",
  "web.terms.meta.description": "The terms and conditions for using SpiralClass.",
  "web.privacyNotice.meta.title": "Privacy policy",
  "web.privacyNotice.meta.description":
    "How SpiralClass collects, uses and protects your personal data, under UK GDPR.",
  "web.about.eyebrow": "Founded by a teacher and a developer",
  "web.about.headline": "Why SpiralClass exists",
  "web.about.sub":
    "Not a feature list built for a pitch deck — a set of problems one teacher actually lived, solved one at a time.",
  "web.about.whoBuiltIt": "Who built it",
  "web.about.founders.jay.role": "Founder — the developer",
  "web.about.founders.jay.bio":
    "Software developer. He built SpiralClass for a working teacher's real problem, not an abstract idea — which is why every feature exists for a reason: someone needed it first.",
  "web.about.ourWhy.title": "Our why",
  "web.about.ourWhy.body":
    "Independent teachers do the hardest part — teaching well — and then lose hours to scheduling, chasing payments, and repeating themselves over WhatsApp. SpiralClass exists so that admin work never costs a teacher a class, or a student a lesson.",
  "web.about.whyTrust": "Why you can trust it",
  "web.about.trust.stripe.title": "Payments processed by Stripe",
  "web.about.trust.stripe.body":
    "SpiralClass never stores your card details. Charges go through Stripe, the same processor used by Amazon and millions of businesses worldwide.",
  "web.about.trust.dataProtected.title": "Your data, protected",
  "web.about.trust.dataProtected.body":
    "Encryption in transit, restricted access, and a plain-language privacy notice about what we keep and why.",
  "web.about.trust.realTeacher.title": "Built with a real teacher",
  "web.about.trust.realTeacher.body":
    "Every feature was tested in a working teacher's real classes before it ever reached anyone else.",
  "web.about.trust.globalPay.title": "Get paid, wherever you are",
  "web.about.trust.globalPay.body":
    "By card through Stripe where it's available, or direct bank transfer through Wise everywhere else — there's always a way to get paid.",
  // {licence} is the SPDX identifier from packages/shared/src/source-code.ts,
  // interpolated so the three locales can't drift from the LICENSE file.
  "web.about.trust.openSource.title": "Open source",
  "web.about.trust.openSource.body":
    "The whole platform is public on GitHub under the {licence} licence — anyone can read exactly how classes, student data and payments are handled here.",
  "web.about.trust.openSource.link": "Read the code on GitHub",
  "web.about.seeFeatures": "See features",
  "web.trialBand.title": "Start your 30-day free trial.",
  "web.trialBand.noCard": "No credit card required.",
  "web.trialBand.createAccount": "Create free account",
  "web.features.meta.title": "Features",
  "web.features.meta.description": "Everything SpiralClass does for teachers of any subject.",
  "web.features.headline": "Everything you need to teach",
  "web.features.sub":
    "SpiralClass handles the admin so you can focus on teaching — whatever subject you teach.",
  "web.features.item.booking.title": "Public booking page",
  "web.features.item.booking.body":
    "One link you share on WhatsApp. Students see your availability, book, and pay — without any extra work from you.",
  "web.features.item.calendar.title": "Calendar with day, week, and month views",
  "web.features.item.calendar.body":
    "See your classes in the format you prefer. Never confuse schedules or miss a booking again.",
  "web.features.item.getPaid.title": "Get paid without chasing",
  "web.features.item.getPaid.body":
    "Prepaid packages by card (Stripe) or Wise. The money arrives before the class — not after.",
  "web.features.item.globalPay.title": "Flexible payments, any country",
  "web.features.item.globalPay.body":
    "Card via Stripe where supported, or direct bank transfer via Wise everywhere else. You choose the rail — your students can always pay you.",
  "web.features.item.reminders.title": "Automatic reminders",
  "web.features.item.reminders.body":
    "Push and email at 24 hours, 1 hour, and 15 minutes before. Fewer no-shows, zero extra work.",
  "web.features.item.chat.title": "Built-in class chat",
  "web.features.item.chat.body":
    "Messages and video right inside the class. No jumping to other apps — everything in one place.",
  "web.features.item.materials.title": "Scheduled materials",
  "web.features.item.materials.body":
    "Upload files or paste links. Choose when to send them — at confirmation, 5 days before, or 1 hour before.",
  "web.features.item.library.title": "Level-tagged material library",
  "web.features.item.library.body":
    "Organize resources by level and assign them to multiple students at once. Create once, reuse always.",
  "web.features.item.notes.title": "Per-student notes and progress",
  "web.features.item.notes.body":
    "A profile for each student with notes, class history, and assigned materials — all at a glance.",
  "web.features.item.pricing.title": "Packages and custom pricing",
  "web.features.item.pricing.body":
    "Define class packages, per-session prices, and adjust the rate per student whenever you need.",
  "web.features.item.homeScreen.title": "Add it to your home screen",
  "web.features.item.homeScreen.body":
    "Install SpiralClass from your browser. Your schedule and students always in your pocket.",
  "web.features.item.videoLessons.title": "Built-in video classroom",
  "web.features.item.videoLessons.body":
    "Teach right inside SpiralClass — no Zoom links, no separate app. Video, notes, and materials on the same screen.",
  "web.features.item.liveCaptions.title": "Live captions & translation",
  "web.features.item.liveCaptions.body":
    "You speak Spanish and your student reads English subtitles in real time. Toggled on with a tap, never stored.",
  "web.features.item.videoCoach.title": "Intro-video AI coach",
  "web.features.item.videoCoach.body":
    "Add a short intro video to your booking page and get AI feedback on it — strengths, concrete improvements, and an overall take, in your language.",
  "web.features.item.srs.title": "Spaced-repetition vocabulary",
  "web.features.item.srs.body":
    "Vocabulary from your classes feeds a spaced-repetition schedule (SM-2) that brings it back right before it's forgotten.",
  "web.features.item.calendarSync.title": "Calendar sync",
  "web.features.item.calendarSync.body":
    "Two-way Google Calendar and a subscribable iCal feed — your classes live alongside everything else in your day.",
  "web.features.seePricing": "See pricing",
